USE  customer_churn_analysis;

CREATE TABLE customers (
                        CustomerID VARCHAR (20) PRIMARY KEY, 
                        Count INT, 
                        Country VARCHAR (50), 
                        State VARCHAR (50), 
                        City VARCHAR (50), 
                        ZipCode VARCHAR (10), 
                        LatLong VARCHAR (50), 
                        Latitude DECIMAL (10,6) , 
                        Longitude DECIMAL (10,6), 
                        Gender VARCHAR (10), 
                        SeniorCitizen VARCHAR (5), 
                        Partner VARCHAR(5),
						Dependents VARCHAR(5),
						Tenure_Months INT,
						Tenure_Group VARCHAR(30),
						Phone_Service VARCHAR(5),
						Multiple_Lines VARCHAR(5),
						Internet_Service VARCHAR(30),
						Online_Security VARCHAR(5),
						Online_Backup VARCHAR(5),
						Device_Protection VARCHAR(5),
						Tech_Support VARCHAR(5),
						Streaming_TV VARCHAR(5),
						Streaming_Movies VARCHAR(5),
						Contract VARCHAR(30),
						Paperless_Billing VARCHAR(5),
						Payment_Method VARCHAR(50),
						Monthly_Charges DECIMAL(10,2),
						Monthly_Charge_Category VARCHAR(20),
						Total_Charges DECIMAL(10,2),
						Churn_Label VARCHAR(5),
						Churn_Value TINYINT,
						Churn_Score INT,
						Risk_Level VARCHAR(20),
						CLTV INT,
						Churn_Category VARCHAR(50),
						Churn_Reason VARCHAR(255)
);















